package com.singtel.redemptionservice;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.test.context.ActiveProfiles;import org.springframework.beans.factory.annotation.Autowired;import java.util.*;import java.util.concurrent.*;import java.time.Instant;import com.singtel.platformcommon.DomainError;import com.singtel.platformcommon.OutboxRepository;
@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT,properties={"spring.datasource.url=jdbc:h2:mem:redemptiontest;MODE=PostgreSQL;DB_CLOSE_DELAY=-1","spring.jpa.hibernate.ddl-auto=create-drop"}) @ActiveProfiles("local") class RedemptionTransactionTest{
@Autowired RedemptionTransactions tx;@Autowired RedemptionRepository repo;@Autowired LedgerRepository ledgers;@Autowired OutboxRepository outbox;
UUID id;Map<String,Object> offer;
@BeforeEach void prepare(){repo.deleteAll();ledgers.deleteAll();outbox.deleteAll();id=UUID.randomUUID();ledgers.save(new CampaignLedger(id));offer=Map.of("eligible",true,"promotion",Map.of("totalRedemptionLimit",7,"perCustomerLimit",1,"discountType","FIXED","discountValue","10.00","budgetLimit","70.00","currency","SGD","endAt",Instant.now().plusSeconds(3600).toString()),"customer",Map.of("spend","50.00"));}
@Test void capacityHoldsUnderConcurrentRequests()throws Exception{var executor=Executors.newFixedThreadPool(6);try{var futures=new ArrayList<Future<Boolean>>();for(int i=0;i<24;i++){int n=i;futures.add(executor.submit(()->{try{tx.redeem(id,"C"+n,"key-"+n,"manager","trace",offer);return true;}catch(DomainError e){assertEquals("LIMIT_EXHAUSTED",e.code);return false;}}));}int successes=0;for(var f:futures)if(f.get(30,TimeUnit.SECONDS))successes++;assertEquals(7,successes);assertEquals(7,repo.count());assertEquals(7,ledgers.findById(id).orElseThrow().redeemed);assertEquals(7,outbox.count());}finally{executor.shutdownNow();}}
@Test void retryReturnsOriginalAndRejectsPayloadMismatch(){var first=tx.redeem(id,"C1","stable-key","manager","trace",offer);var second=tx.redeem(id,"C1","stable-key","manager","trace",offer);assertEquals(first.id,second.id);assertEquals(1,repo.count());assertThrows(DomainError.class,()->tx.redeem(id,"C2","stable-key","manager","trace",offer));}
@Test void concurrentCancellationReleasesCapacityOnce()throws Exception{var r=tx.redeem(id,"C1","cancel-key","manager","trace",offer);var pool=Executors.newFixedThreadPool(2);try{var a=pool.submit(()->tx.cancel(r.id));var b=pool.submit(()->tx.cancel(r.id));assertEquals("CANCELLED",a.get().status);assertEquals("CANCELLED",b.get().status);assertEquals(0,ledgers.findById(id).orElseThrow().redeemed);assertEquals(0,ledgers.findById(id).orElseThrow().spent.signum());assertEquals(2,outbox.count());}finally{pool.shutdownNow();}}
@Test void perCustomerLimitAndIneligibleFailClosed(){tx.redeem(id,"C1","customer-key1","manager","trace",offer);assertThrows(DomainError.class,()->tx.redeem(id,"C1","customer-key2","manager","trace",offer));var no=new HashMap<>(offer);no.put("eligible",false);assertThrows(DomainError.class,()->tx.redeem(id,"C2","ineligible-key","manager","trace",no));assertEquals(1,repo.count());}
}
